import { defineComponent, nextTick, ref } from 'wevu'

const samples = []

defineComponent({
  setData: {
    debugPhases: true,
    debugWhen: 'always',
    debugSampleRate: 1,
    debug(info) { samples.push(info) },
  },
  setup() {
    const count = ref(0)
    const items = ref([])
    async function increment() {
      samples.length = 0
      count.value++
      items.value.push({ id: count.value, label: `库存 ${count.value}` })
      await nextTick()
      console.log('已经显示', {
        setDataCalls: samples.length,
        payloadBytes: samples.reduce((sum, info) => sum + (info.payloadBytes ?? 0), 0),
      })
    }
    return { count, items, increment }
  },
})

