import { createReactMiniProgramRoot } from '@weapp-vite/react'
import { createElement } from 'react'

let root

export function mount(page, title) {
  root = createReactMiniProgramRoot(page)
  root.render(createElement('view', null, title))
}

export function forward(event) {
  root?.dispatchEvent(event)
}

export function unmount() {
  root?.unmount()
  root = undefined
}

